<template>
  <div class="chat-page">

    <!-- Chưa có tin nhắn -->
    <div v-if="messages.length === 0" class="empty-chat">
      <div class="welcome-title">
        Chúng ta nên bắt đầu từ đâu?
      </div>
    </div>

    <!-- Có tin nhắn -->
    <div
      v-else
      ref="messageArea"
      class="message-area"
    >
      <div
        v-for="(item, index) in messages"
        :key="index"
        class="message-row"
        :class="item.role"
      >
        <div class="message-content">

          <!-- YouTube trong tin nhắn -->
          <div
            v-if="item.youtube"
            class="youtube-message"
          >
            <div class="youtube-frame-wrap">
              <iframe
                class="youtube-frame"
                :src="'https://www.youtube-nocookie.com/embed/' + item.youtube.id"
                title="YouTube video"
                frameborder="0"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                allowfullscreen
              ></iframe>
            </div>

            <a
              class="youtube-link"
              :href="item.youtube.url"
              target="_blank"
              rel="noopener noreferrer"
            >
              {{ item.youtube.url }}
            </a>
          </div>

          <!-- Hình ảnh trong tin nhắn -->
          <div
            v-if="item.images && item.images.length"
            class="message-images"
          >
            <img
              v-for="(img, imgIndex) in item.images"
              :key="imgIndex"
              :src="img"
              class="message-image"
              alt="Ảnh đã gửi"
            >
          </div>

          <!-- Nội dung text -->
          <div
            v-if="item.text"
            class="message-bubble"
          >
            {{ item.text }}
          </div>

        </div>
      </div>
    </div>

    <!-- INPUT -->
    <div class="composer-wrap">

      <div class="composer-container">

        <!-- Preview hình vừa paste/chọn -->
        <div
          v-if="pasteImages.length"
          class="image-preview-list"
        >
          <div
            v-for="(img, index) in pasteImages"
            :key="index"
            class="image-preview-item"
          >
            <img :src="img" alt="Ảnh xem trước">

            <button
              class="remove-image"
              type="button"
              title="Xóa ảnh"
              @click="removeImage(index)"
            >
              ×
            </button>
          </div>
        </div>

        <!-- Preview YouTube khi dán link -->
        <div
          v-if="draftYoutube"
          class="youtube-preview"
        >
          <div class="youtube-preview-main">
            <div class="youtube-preview-thumb">
              <img
                :src="'https://img.youtube.com/vi/' + draftYoutube.id + '/hqdefault.jpg'"
                alt="YouTube preview"
              >
              <div class="youtube-play">▶</div>
            </div>

            <div class="youtube-preview-info">
              <strong>YouTube</strong>
              <span>{{ draftYoutube.url }}</span>
            </div>
          </div>

          <button
            class="youtube-remove"
            type="button"
            title="Bỏ YouTube"
            @click="removeDraftYoutube"
          >
            ×
          </button>
        </div>

        <div class="composer">

          <!-- Chọn ảnh bằng nút + -->
          <div class="attach-box">

            <button
              class="plus-btn"
              type="button"
              title="Thêm hình ảnh"
              @click.stop="onPlusClick"
            >
              +
            </button>

            <!-- Menu riêng cho mobile -->
            <div
              v-if="showAttachMenu"
              class="mobile-attach-menu"
              @click.stop
            >
              <button
                type="button"
                @click="pasteImageFromClipboard"
              >
                <span>📋</span>
                Dán hình
              </button>

              <button
                type="button"
                @click="pasteYoutubeFromClipboard"
              >
                <span>▶️</span>
                Dán YouTube
              </button>

              <button
                type="button"
                @click="openImagePicker"
              >
                <span>🖼️</span>
                Thư viện
              </button>

              <button
                type="button"
                @click="openCameraPicker"
              >
                <span>📷</span>
                Chụp ảnh
              </button>
            </div>

          </div>

          <!-- Chọn ảnh từ thư viện -->
          <input
            ref="imagePicker"
            class="image-picker"
            type="file"
            accept="image/*"
            multiple
            @change="handleImageSelect"
          >

          <!-- Chụp ảnh bằng camera mobile -->
          <input
            ref="cameraPicker"
            class="image-picker"
            type="file"
            accept="image/*"
            capture="environment"
            @change="handleCameraSelect"
          >

          <input
            ref="messageInput"
            v-model="message"
            class="message-input"
            placeholder="Hỏi bất kỳ điều gì"
            @keyup.enter="sendMessage"
            @paste="handlePaste"
          >

          <div class="composer-right">

            <button
              class="mode-btn"
              type="button"
            >
              Cao
              <span>⌄</span>
            </button>

            <button
              class="mic-btn"
              type="button"
            >
              🎙
            </button>

            <button
              class="send-btn"
              type="button"
              :disabled="!canSend"
              @click="sendMessage"
            >
              ↑
            </button>

          </div>

        </div>

        <div
          v-if="pasteNotice"
          class="paste-notice"
        >
          {{ pasteNotice }}
        </div>

      </div>

    </div>

  </div>
</template>

<script>
export default {
  name: "ChatView",

  data() {
    return {
      message: "",
      messages: [],
      pasteImages: [],
      showAttachMenu: false,
      pasteNotice: "",
      pasteNoticeTimer: null,

      // IndexedDB
      idbLoaded: false,
      idbSaveTimer: null
    };
  },

  computed: {
    canSend() {
      return (
        this.message.trim().length > 0 ||
        this.pasteImages.length > 0
      );
    },

    // Tự nhận diện link YouTube đang có trong ô nhập.
    draftYoutube() {
      return this.getYoutubeData(this.message);
    }
  },

  watch: {
    // Tự động lưu khi nội dung chat thay đổi.
    messages: {
      deep: true,
      handler() {
        this.scheduleSaveToIdb();
      }
    },

    // Lưu cả nội dung đang gõ dở.
    message() {
      this.scheduleSaveToIdb();
    },

    // Lưu các ảnh đang chờ gửi.
    pasteImages: {
      deep: true,
      handler() {
        this.scheduleSaveToIdb();
      }
    }
  },

  async mounted() {
    await this.loadChatFromIdb();

    this.$nextTick(() => {
      if (this.$refs.messageInput) {
        this.$refs.messageInput.focus();
      }

      const area = this.$refs.messageArea;
      if (area) {
        area.scrollTop = area.scrollHeight;
      }
    });
  },

  beforeDestroy() {
    if (this.pasteNoticeTimer) {
      clearTimeout(this.pasteNoticeTimer);
    }

    if (this.idbSaveTimer) {
      clearTimeout(this.idbSaveTimer);
      this.idbSaveTimer = null;
    }

    // Cố gắng lưu lần cuối trước khi component bị hủy.
    if (this.idbLoaded) {
      this.saveChatToIdb();
    }
  },

  methods: {

    // =========================
    // INDEXEDDB
    // =========================
    openChatDb() {
      return new Promise((resolve, reject) => {
        // Tách DB theo thư mục app, ví dụ /Test1/ và /Test2/ không dùng chung dữ liệu.
        const appKey =
          window.location.pathname.split("/").filter(Boolean)[0] || "root";

        const request = indexedDB.open("VueChatDB_" + appKey, 1);

        request.onupgradeneeded = event => {
          const db = event.target.result;

          if (!db.objectStoreNames.contains("chatState")) {
            db.createObjectStore("chatState");
          }
        };

        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });
    },

    async loadChatFromIdb() {
      if (!window.indexedDB) {
        console.warn("Trình duyệt không hỗ trợ IndexedDB.");
        this.idbLoaded = true;
        return;
      }

      try {
        const db = await this.openChatDb();

        const state = await new Promise((resolve, reject) => {
          const tx = db.transaction("chatState", "readonly");
          const store = tx.objectStore("chatState");
          const request = store.get("main");

          request.onsuccess = () => resolve(request.result || null);
          request.onerror = () => reject(request.error);
        });

        db.close();

        if (state) {
          this.messages = Array.isArray(state.messages)
            ? state.messages
            : [];

          this.message = typeof state.message === "string"
            ? state.message
            : "";

          this.pasteImages = Array.isArray(state.pasteImages)
            ? state.pasteImages
            : [];
        }
      }
      catch (error) {
        console.error("Không thể đọc dữ liệu chat từ IndexedDB:", error);
      }
      finally {
        this.idbLoaded = true;
      }
    },

    scheduleSaveToIdb() {
      if (!this.idbLoaded) {
        return;
      }

      if (this.idbSaveTimer) {
        clearTimeout(this.idbSaveTimer);
      }

      // Debounce để không ghi DB sau mỗi phím bấm.
      this.idbSaveTimer = setTimeout(() => {
        this.idbSaveTimer = null;
        this.saveChatToIdb();
      }, 300);
    },

    async saveChatToIdb() {
      if (!window.indexedDB) {
        return;
      }

      const state = {
        messages: this.messages,
        message: this.message,
        pasteImages: this.pasteImages,
        updatedAt: new Date().toISOString()
      };

      try {
        const db = await this.openChatDb();

        await new Promise((resolve, reject) => {
          const tx = db.transaction("chatState", "readwrite");
          const store = tx.objectStore("chatState");

          store.put(state, "main");

          tx.oncomplete = () => resolve();
          tx.onerror = () => reject(tx.error);
          tx.onabort = () => reject(tx.error);
        });

        db.close();
      }
      catch (error) {
        console.error("Không thể lưu dữ liệu chat vào IndexedDB:", error);
      }
    },

    async clearChatIdb() {
      try {
        const db = await this.openChatDb();

        await new Promise((resolve, reject) => {
          const tx = db.transaction("chatState", "readwrite");
          const store = tx.objectStore("chatState");

          store.delete("main");

          tx.oncomplete = () => resolve();
          tx.onerror = () => reject(tx.error);
        });

        db.close();

        this.messages = [];
        this.message = "";
        this.pasteImages = [];
      }
      catch (error) {
        console.error("Không thể xóa dữ liệu chat trong IndexedDB:", error);
      }
    },

    // =========================
    // PASTE HÌNH: Ctrl + V
    // =========================
    handlePaste(event) {

      const clipboardData = event.clipboardData;

      if (!clipboardData) {
        return;
      }

      // 1. Ưu tiên hình ảnh trong clipboard.
      if (clipboardData.items) {

        const imageFiles = [];

        for (let i = 0; i < clipboardData.items.length; i++) {

          const item = clipboardData.items[i];

          if (
            item.kind === "file" &&
            item.type &&
            item.type.indexOf("image/") === 0
          ) {
            const file = item.getAsFile();

            if (file) {
              imageFiles.push(file);
            }
          }
        }

        if (imageFiles.length) {

          event.preventDefault();

          imageFiles.forEach(file => {
            this.addImageFile(file);
          });

          return;
        }
      }

      // 2. Nếu là text thì kiểm tra link YouTube.
      const pastedText =
        clipboardData.getData("text/plain") || "";

      const youtube =
        this.getYoutubeData(pastedText);

      if (youtube) {

        event.preventDefault();

        // Chèn URL vào vị trí con trỏ hiện tại.
        this.insertTextAtCursor(pastedText);

        this.$nextTick(() => {
          if (this.$refs.messageInput) {
            this.$refs.messageInput.focus();
          }
        });
      }
    },


    // =========================
    // YOUTUBE
    // =========================
    getYoutubeData(text) {

      if (!text) {
        return null;
      }

      // Tìm URL đầu tiên trong chuỗi.
      const urlMatch =
        String(text).match(/https?:\/\/[^\s]+/i);

      if (!urlMatch) {
        return null;
      }

      let rawUrl =
        urlMatch[0].replace(/[),.;!?]+$/, "");

      try {

        const url = new URL(rawUrl);
        const host =
          url.hostname.replace(/^www\./, "").toLowerCase();

        let id = "";

        // youtu.be/VIDEO_ID
        if (host === "youtu.be") {
          id = url.pathname.split("/").filter(Boolean)[0] || "";
        }

        // youtube.com/...
        if (
          host === "youtube.com" ||
          host === "m.youtube.com" ||
          host === "music.youtube.com" ||
          host === "youtube-nocookie.com"
        ) {

          if (url.pathname === "/watch") {
            id = url.searchParams.get("v") || "";
          }
          else {

            const parts =
              url.pathname.split("/").filter(Boolean);

            if (
              parts.length >= 2 &&
              ["shorts", "embed", "live"].includes(parts[0])
            ) {
              id = parts[1];
            }
          }
        }

        // YouTube video id thường dài 11 ký tự.
        if (!/^[A-Za-z0-9_-]{11}$/.test(id)) {
          return null;
        }

        return {
          id: id,
          url: rawUrl
        };
      }
      catch (error) {
        return null;
      }
    },


    insertTextAtCursor(text) {

      const input = this.$refs.messageInput;

      if (!input) {
        this.message += text;
        return;
      }

      const start =
        typeof input.selectionStart === "number"
          ? input.selectionStart
          : this.message.length;

      const end =
        typeof input.selectionEnd === "number"
          ? input.selectionEnd
          : start;

      this.message =
        this.message.slice(0, start) +
        text +
        this.message.slice(end);

      this.$nextTick(() => {

        const cursor =
          start + text.length;

        input.focus();

        if (input.setSelectionRange) {
          input.setSelectionRange(cursor, cursor);
        }
      });
    },


    removeDraftYoutube() {

      const youtube =
        this.getYoutubeData(this.message);

      if (!youtube) {
        return;
      }

      this.message =
        this.message
          .replace(youtube.url, "")
          .replace(/\s{2,}/g, " ")
          .trim();

      this.$nextTick(() => {
        if (this.$refs.messageInput) {
          this.$refs.messageInput.focus();
        }
      });
    },


    async pasteYoutubeFromClipboard() {

      this.showAttachMenu = false;

      if (
        !navigator.clipboard ||
        typeof navigator.clipboard.readText !== "function"
      ) {
        this.showPasteNotice(
          "Trình duyệt chưa hỗ trợ đọc link clipboard. Hãy dán link vào ô nhập."
        );
        return;
      }

      try {

        const clipboardText =
          await navigator.clipboard.readText();

        const youtube =
          this.getYoutubeData(clipboardText);

        if (!youtube) {
          this.showPasteNotice(
            "Clipboard không có link YouTube hợp lệ."
          );
          return;
        }

        // Giữ nguyên toàn bộ text được copy.
        if (this.message.trim()) {
          this.message += " " + clipboardText.trim();
        }
        else {
          this.message = clipboardText.trim();
        }

        this.showPasteNotice(
          "Đã dán link YouTube."
        );

        this.$nextTick(() => {
          if (this.$refs.messageInput) {
            this.$refs.messageInput.focus();
          }
        });
      }
      catch (error) {

        console.warn(
          "Không thể đọc YouTube từ clipboard:",
          error
        );

        this.showPasteNotice(
          "Không thể đọc clipboard. Hãy nhấn giữ trong ô nhập và chọn Dán."
        );
      }
    },


    // =========================
    // NÚT + : desktop mở thư viện,
    // mobile mở menu Dán/Thư viện/Camera
    // =========================
    onPlusClick() {

      const isMobile =
        window.matchMedia &&
        window.matchMedia("(max-width: 600px)").matches;

      if (isMobile) {
        this.showAttachMenu = !this.showAttachMenu;
        return;
      }

      this.openImagePicker();
    },


    // =========================
    // DÁN HÌNH TRÊN MOBILE
    // Dùng Clipboard API khi trình duyệt hỗ trợ.
    // =========================
    async pasteImageFromClipboard() {

      this.showAttachMenu = false;

      if (
        !navigator.clipboard ||
        typeof navigator.clipboard.read !== "function"
      ) {
        this.showPasteNotice(
          "Trình duyệt này chưa hỗ trợ dán ảnh trực tiếp. Hãy chọn Thư viện hoặc Chụp ảnh."
        );
        return;
      }

      try {

        const clipboardItems =
          await navigator.clipboard.read();

        let foundImage = false;

        for (const clipboardItem of clipboardItems) {

          const imageTypes =
            clipboardItem.types.filter(type =>
              type.indexOf("image/") === 0
            );

          for (const imageType of imageTypes) {

            const blob =
              await clipboardItem.getType(imageType);

            this.addImageFile(blob);

            foundImage = true;
          }
        }

        if (foundImage) {
          this.showPasteNotice("Đã dán hình từ clipboard.");
        }
        else {
          this.showPasteNotice(
            "Clipboard hiện không có hình ảnh."
          );
        }

      }
      catch (error) {

        console.warn(
          "Không thể đọc hình từ clipboard:",
          error
        );

        this.showPasteNotice(
          "Trình duyệt không cho phép đọc clipboard. Hãy chọn Thư viện hoặc Chụp ảnh."
        );
      }
    },


    showPasteNotice(text) {

      this.pasteNotice = text;

      if (this.pasteNoticeTimer) {
        clearTimeout(this.pasteNoticeTimer);
      }

      this.pasteNoticeTimer =
        setTimeout(() => {
          this.pasteNotice = "";
          this.pasteNoticeTimer = null;
        }, 3500);
    },


    // =========================
    // NÚT + CHỌN HÌNH
    // =========================
    openImagePicker() {

      this.showAttachMenu = false;

      if (this.$refs.imagePicker) {
        this.$refs.imagePicker.click();
      }
    },


    openCameraPicker() {

      this.showAttachMenu = false;

      if (this.$refs.cameraPicker) {
        this.$refs.cameraPicker.click();
      }
    },


    handleImageSelect(event) {

      const files = Array.from(
        event.target.files || []
      );

      files.forEach(file => {
        if (file.type && file.type.indexOf("image/") === 0) {
          this.addImageFile(file);
        }
      });

      // Cho phép chọn lại cùng một file
      event.target.value = "";
    },


    handleCameraSelect(event) {

      const files = Array.from(
        event.target.files || []
      );

      files.forEach(file => {
        if (
          file.type &&
          file.type.indexOf("image/") === 0
        ) {
          this.addImageFile(file);
        }
      });

      event.target.value = "";
    },


    // =========================
    // FILE -> BASE64
    // =========================
    addImageFile(file) {

      const reader = new FileReader();

      reader.onload = e => {
        this.pasteImages.push(e.target.result);
      };

      reader.readAsDataURL(file);
    },


    removeImage(index) {
      this.pasteImages.splice(index, 1);

      this.$nextTick(() => {
        if (this.$refs.messageInput) {
          this.$refs.messageInput.focus();
        }
      });
    },


    // =========================
    // SEND
    // =========================
    sendMessage() {

      const text = this.message.trim();

      if (
        !text &&
        this.pasteImages.length === 0
      ) {
        return;
      }

      const youtube =
        this.getYoutubeData(text);

      this.messages.push({
        role: "user",
        text: text,
        images: this.pasteImages.slice(),
        youtube: youtube
      });

      this.message = "";
      this.pasteImages = [];
      this.showAttachMenu = false;

      this.$nextTick(() => {

        const area = this.$refs.messageArea;

        if (area) {
          area.scrollTop = area.scrollHeight;
        }

        if (this.$refs.messageInput) {
          this.$refs.messageInput.focus();
        }

      });
    }

  }
};
</script>

